const { MessageClient } = require('discord.js');
const client = new MessageClient();

client.on('ready', () => {
  console.log(`Logged in as ${client.user.tag}`);
});

client.on('message', (message) => {
  if (message.content.startsWith('!ban')) {
    const args = message.content.split(' ').slice(1);
    if (args.length < 2) {
      return message.reply('Usage: !ban <user>');
    }

    const user = message.guild.members.cache.find(m => m.id === args[1]);
    if (!user) {
      return message.reply('User not found');
    }

    user.ban({ reason: 'Banned by bot' });
    message.reply(`Banned ${user.tag}`);
  }
});

client.login('YOUR_BOT_TOKEN');
```

Replace `'YOUR_BOT_TOKEN'` with your actual bot token. This bot listens for the `!ban` command, takes the user ID as an argument, and bans the user from the server. The bot responds with a message indicating the user has been banned.

Make sure to grant the necessary permissions to the bot to ban users in your server.

